  "exports.lockedTitle": "การส่งออก CSV และ Excel เป็นฟีเจอร์ของ Business",
  "exports.lockedDesc": "พื้นที่ทำงานของคุณใช้แผน Essentials อยู่ Business เพิ่มการส่งออก CSV และ Excel การประเมินมูลค่าสต็อก สินค้าและพนักงานไม่จำกัด ซัพพลายเออร์ การจัดซื้อ และชุดสินค้า",
  "exports.seeBusiness": "ดูสิ่งที่ Business มีให้",
  "exports.whatTheseAre": "ไฟล์เหล่านี้คืออะไร",
  "exports.about1": "ทุกชุดข้อมูลมาในรูปแบบ CSV หรือสมุดงาน Excel จริง (.xlsx) — สมุดงานสินค้าคงคลังฉบับเต็มเป็น Excel เท่านั้น โดยมีหนึ่งชีตต่อหนึ่งชุดข้อมูล ไฟล์ CSV เปิดได้ใน Excel, Numbers, Google Sheets และแอปสต็อกส่วนใหญ่ ข้อความ UTF-8 เครื่องหมายจุลภาคในเครื่องหมายคำพูด การขึ้นบรรทัดใหม่ในบันทึก และเลขศูนย์นำหน้าในรหัสจะถูกเก็บไว้ทั้งหมด และเซลล์ที่ขึ้นต้นเหมือนสูตรจะถูกทำให้เป็นกลาง เพื่อให้สเปรดชีตเปิดเป็นข้อความ",
  "exports.about2": "ในไฟล์ Excel รหัส SKU, UPC, ISBN และบาร์โค้ดจะเป็นเซลล์ข้อความ — ไม่เป็นสัญกรณ์วิทยาศาสตร์และไม่ตัดเลขศูนย์ออกเลย — พร้อมความกว้างคอลัมน์ ตัวกรองส่วนหัว และรูปแบบสกุลเงินหรือจำนวนที่กำหนดไว้ สมุดงานสินค้าคงคลังฉบับเต็มเก็บสินค้า ระดับสต็อก สถานที่ และความเคลื่อนไหวไว้ในชีตแยกกัน",
  "exports.about3": "การส่งออกขนาดใหญ่มากจะหยุดที่ 20,000 แถวต่อชุดข้อมูล — เมื่อเกิดเหตุการณ์นั้น ชื่อไฟล์จะระบุไว้ (truncated-20000) เพื่อให้ไฟล์บางส่วนไม่มีวันแอบอ้างว่าเป็นไฟล์ฉบับสมบูรณ์",
  "exports.about4": "ข้อมูลสำรองเป็นภาพรวมของข้อมูลของคุณ ไม่ใช่การกู้คืนในคลิกเดียว การกู้คืนเป็นงานแบบทำด้วยมือและตรวจทานก่อน ดังนั้นเก็บไฟล์ไว้ให้ปลอดภัย — ยังไม่มีสิ่งใดในแอปที่สร้างธุรกิจที่ถูกลบขึ้นใหม่จากไฟล์นี้ได้ โค้ดของแอปและข้อมูลสำรองของแพลตฟอร์ม Base44 ได้รับการจัดการแยกจากไฟล์เหล่านี้",
  "exports.about5": "รูปภาพและไฟล์แนบจะแสดงเป็นลิงก์ที่จัดเก็บไว้ — ไฟล์รูปภาพเองไม่ได้ถูกรวมอยู่ในไฟล์ดาวน์โหลด",
  "exports.backupTitle": "ข้อมูลสำรองฉบับเต็ม",
  "exports.backupDesc": "ไฟล์เดียวที่มีสินค้า สถานที่ ระดับสต็อก บัญชีความเคลื่อนไหวฉบับสมบูรณ์ ซัพพลายเออร์ การจัดซื้อ คำสั่งซื้อ การคืนสินค้า การนับสต็อก และรายการประกาศของธุรกิจนี้ — พร้อมการตั้งค่าโปรไฟล์ของธุรกิจ เก็บไว้ในที่ที่คุณควบคุม",
