  "print.howToReach": "วิธีเข้าถึงเครื่องพิมพ์ของคุณ",
  "print.howIntro": "แอปนี้เชื่อมต่อกับเครื่องพิมพ์ที่คุณมีอยู่แล้ว — ไม่ใช่เครื่องพิมพ์ในตัวเอง มีสี่วิธีในการเข้าถึงเครื่องพิมพ์ และป้ายพิมพ์ได้ในทั้งสองแผนผ่านทุกวิธี ใบแพ็กสินค้า ใบสั่งซื้อ เอกสารซัพพลายเออร์ และรายงานเป็นของ Business เท่านั้น ไม่ว่าจะเชื่อมต่อด้วยวิธีใด",
  "print.howBluetoothLead": "Bluetooth",
  "print.howBluetoothBody": "จากหน้านี้ บน Chrome หรือ Edge บนเดสก์ท็อป และบน Chrome บน Android: เลือกเครื่องพิมพ์ป้ายของคุณแล้วป้ายจะส่งตรงไปที่นั่น ใช้ไม่ได้ใน Safari บน iOS — บน iPhone การพิมพ์ผ่าน Bluetooth มากับแอปมือถือแทน เครื่องพิมพ์ที่พูดเฉพาะภาษา ZPL ของ Zebra หรือภาษาเฉพาะของ Brother จะไม่เข้าใจป้ายที่หน้านี้ส่งไป ซึ่งจะตรวจสอบกับเครื่องพิมพ์จริงก่อนที่จะเรียกว่าใช้งานได้",
  "print.howWifiLead": "Wi-Fi",
  "print.howWifiBody": "ติดตั้งเครื่องพิมพ์บน Wi-Fi ของร้านของคุณ จากนั้นใช้ปุ่มพิมพ์ — จะพิมพ์ผ่านเครื่องพิมพ์ที่ติดตั้งบนคอมพิวเตอร์เครื่องนี้ ผ่านเครือข่ายของร้าน บน iPhone นั้น AirPrint มีมาในตัว: เครื่องพิมพ์ AirPrint บน Wi-Fi เดียวกันจะปรากฏในชีตการพิมพ์ ไม่ต้องใช้สายและไม่ต้องใช้แอป และแอปไม่ต้องใช้โค้ดเฉพาะสำหรับ AirPrint เครื่องพิมพ์ต้องรองรับ AirPrint (เครื่องรุ่นใหม่ส่วนใหญ่รองรับ) และโทรศัพท์กับเครื่องพิมพ์ต้องอยู่บน Wi-Fi เดียวกัน",
  "print.howEthernetLead": "Ethernet",
  "print.howEthernetBody": "ต่อเครื่องพิมพ์เข้ากับเครือข่ายร้านของคุณด้วยสาย Ethernet ติดตั้งบนคอมพิวเตอร์ และพิมพ์ผ่านปุ่มพิมพ์ Ethernet เป็นเส้นทางสำหรับเดสก์ท็อปและคอมพิวเตอร์ — iPhone ไม่ใช้สาย Ethernet",
  "print.howUsbLead": "USB",
  "print.howUsbBody": "เสียบเครื่องพิมพ์เข้ากับคอมพิวเตอร์ด้วยสายของเครื่องและใช้ปุ่มพิมพ์ — จะพิมพ์ผ่านเครื่องพิมพ์ที่ติดตั้งไว้ที่นั่น บนโทรศัพท์ Android ที่มีสาย USB OTG ปุ่ม USB ด้านบนจะคุยตรงกับเครื่องพิมพ์ iPhone ไม่สามารถพิมพ์ผ่าน USB โดยตรงได้ — ไม่มี WebUSB ที่นั่น — ดังนั้นใช้ Wi-Fi / AirPrint หรือ Bluetooth จากแอปมือถือ",
  "print.howCordsLead": "สายยังคงช่วย iPhone ได้ โดยห่างออกไปหนึ่งขั้น",
  "print.howCordsBody": "เครื่องพิมพ์ USB ที่เสียบเข้ากับคอมพิวเตอร์ของร้าน หรือเครื่องพิมพ์ Ethernet ที่ต่อสายเข้ากับเครือข่าย จะปรากฏบน iPhone ของคุณผ่าน Wi-Fi ของร้าน (AirPrint / เครื่องพิมพ์ที่ใช้ร่วมกัน) — สายทำให้เครื่องพิมพ์อยู่บนเครือข่ายอย่างมั่นคง และโทรศัพท์เข้าถึงได้แบบไร้สาย",
  "print.howOfflineLead": "หากอินเทอร์เน็ตหลุด",
  "print.howOfflineBody": "ป้ายและเอกสารที่อยู่บนหน้านี้แล้วจะยังคงพิมพ์ได้ — ปุ่มพิมพ์ PDF ป้าย Bluetooth และ USB ไม่ต้องใช้การเชื่อมต่อ สิ่งที่ต้องใช้อินเทอร์เน็ตคือการโหลดหน้าและสินค้าของหน้าในตอนแรก โหมดออฟไลน์เต็มรูปแบบ (ทำงานในแอปโดยไม่มีการเชื่อมต่อเลย) เป็นงานสร้างแยกที่ใหญ่กว่า และไม่ได้อ้างไว้ที่นี่",
