  "settings.cancelTerms.intro": "นี่คือเงื่อนไขสำหรับสมาชิก Luminous StockHaven แบบชำระเงิน การเรียกเก็บเงินสำหรับการสมัครสมาชิกผ่านเว็บไซต์ดำเนินการผ่าน Stripe คุณสามารถยกเลิกการสมัครสมาชิกด้วยตัวเองได้ทุกเมื่อโดยใช้ปุ่มยกเลิกการสมัครสมาชิกด้านล่าง — ไม่ต้องรอการอนุมัติจากพนักงาน คำขอยกเลิกและคืนเงินสามารถจัดการได้ผ่านช่องทางติดต่อฝ่ายสนับสนุนลูกค้าอย่างเป็นทางการ theluminousbookshop@outlook.com",
  "settings.cancelTerms.noApprovalBody": "คุณสามารถยกเลิกการสมัครสมาชิกด้วยตัวเองได้ทุกเมื่อ ไม่ต้องรอการอนุมัติจากพนักงาน การต่ออายุในอนาคตจะหยุดก็ต่อเมื่อผู้ให้บริการเรียกเก็บเงินยืนยันการยกเลิกแล้วเท่านั้น",
  "settings.cancelTerms.noApprovalTitle": "ยกเลิกโดยไม่ต้องขออนุมัติ:",
  "settings.cancelTerms.paymentBody": "สำหรับการทดลองใช้แบบชำระเงิน การทดลองใช้เจ็ดวันต้องใช้วิธีชำระเงินตอนสมัคร หากไม่ยกเลิกภายในกำหนดยกเลิกทดลองใช้ที่เกี่ยวข้อง แผนรายเดือนที่เลือกจะถูกเรียกเก็บเงินโดยอัตโนมัติหลังจากการทดลองใช้ ราคา วันที่เรียกเก็บเงินครั้งแรก และกำหนดยกเลิกเฉพาะของผู้ให้บริการจะต้องแสดงตอนสมัคร การเรียกเก็บเงินช่วงทดลองใช้ดำเนินการผ่าน Stripe",
  "settings.cancelTerms.paymentTitle": "วิธีชำระเงินและการต่ออายุอัตโนมัติ:",
  "settings.cancelTerms.remainingBody": "หากคุณชำระเงินสำหรับรอบการเรียกเก็บเงินไปแล้ว คุณอาจยังเข้าถึงได้จนถึงวันที่ชำระเงินถึงที่ยืนยันแล้วนั้น การสิ้นสุดก่อนกำหนดต้องมีการยืนยันจากผู้ให้บริการที่เหมาะสมและการจัดการคืนเงินที่เกี่ยวข้อง การเข้าถึงช่วงทดลองใช้ฟรีสิ้นสุดตามวันที่ยุติการทดลองใช้ที่ผู้ให้บริการยืนยัน",
  "settings.cancelTerms.remainingTitle": "สิทธิ์การเข้าถึงที่เหลือ:",
  "settings.cancelTerms.storesBody": "หากคุณสมัครผ่าน Google Play หรือ Apple App Store การสมัครสมาชิกของคุณจะถูกเรียกเก็บเงินและจัดการโดยสโตร์นั้น คุณอาจต้องยกเลิกโดยตรงในส่วนการสมัครสมาชิกของบัญชี Google หรือ Apple เดียวกับที่ใช้สมัคร การยกเลิกการสมัครสมาชิกผ่านเว็บไซต์แยกต่างหาก การถอนการติดตั้งแอปนี้ หรือการขอลบบัญชี Luminous StockHaven ไม่ได้ยกเลิกการสมัครสมาชิกที่เรียกเก็บเงินผ่านสโตร์โดยอัตโนมัติ ตรวจสอบใบเสร็จการซื้อของคุณเพื่อยืนยันว่าใครเรียกเก็บเงินจากคุณ",
  "settings.cancelTerms.storesTitle": "การสมัครสมาชิกผ่าน Google Play และ Apple App Store (หากคุณสมัครผ่านสโตร์):",
