  "payroll.dd.steps.body": "1. คุณต้องมีบัญชีธนาคารสำหรับธุรกิจที่สามารถส่งการชำระเงินแบบ ACH ได้ 2. เก็บแบบฟอร์มอนุญาตที่ลงนามแล้วจากสมาชิกในทีมแต่ละคน — เช็คที่เป็นโมฆะจะช่วยยืนยันตัวเลขได้ 3. ส่งการจ่ายเงินเดือนล่วงหน้า 2-3 วันทำการก่อนวันจ่ายเงิน เพื่อให้เงินเข้าตรงเวลา 4. รัฐส่วนใหญ่กำหนดให้สมาชิกในทีมให้ความยินยอมเป็นลายลักษณ์อักษร แอปนี้จะเก็บแบบฟอร์มและแนะนำขั้นตอนต่าง ๆ ให้คุณ — การส่งเงินจริงจะดำเนินการผ่านธนาคารของคุณเอง",
