  "recovery.doneBody": "อีเมลบัญชีของคุณเปลี่ยนแล้ว และการเข้าสู่ระบบครั้งนี้กลับเป็นการเข้าสู่ระบบปกติของคุณอีกครั้ง ยินดีต้อนรับกลับ",
  "recovery.doneButton": "ดำเนินการต่อไปที่ร้านของฉัน",
  "settings.security.title": "ความปลอดภัยและกุญแจสำรอง",
  "settings.security.description": "ตั้งค่ากุญแจสำรองของคุณก่อนที่คุณจะต้องการ: หากคุณสูญเสียการเข้าถึงอีเมลบัญชีของคุณเมื่อใด กุญแจเหล่านี้คือวิธีที่คุณจะได้ร้านของคุณกลับคืนมา",
  "settings.security.genericError": "เกิดข้อผิดพลาด โปรดลองอีกครั้ง",
  "settings.security.accountEmail": "อีเมลบัญชี",
  "settings.security.backupCodesTitle": "รหัสสำรอง",
  "settings.security.backupCodesDesc": "กุญแจสำรองแบบใช้ครั้งเดียว พิมพ์หรือจดไว้และเก็บไว้ในที่ปลอดภัย — แต่ละรหัสสามารถพาคุณกลับมาได้หนึ่งครั้งหากคุณสูญเสียอีเมลของคุณ",
  "settings.security.codesRemaining": "รหัสสำรองที่ยังไม่ได้ใช้เหลืออยู่: {count}",
