  "crossStore.transferIntro": "ร้านทั้งสองเป็นของคุณ คุณจึงย้ายสต็อกได้โดยตรงโดยไม่ต้องมีคำขอ เลือกสินค้า บอกจำนวนและต้นทาง แล้วเลือกร้านปลายทาง ร้านทั้งสองจะอัปเดตทันที และทั้งสองร้านจะเก็บบันทึกการย้ายครั้งนี้ไว้",
  "crossStore.transferNoTargets": "คุณยังไม่มีร้านอื่นที่เป็นของคุณ — สต็อกจะย้ายได้เฉพาะระหว่างร้านที่เป็นของคุณเท่านั้น",
