  "crossStore.transferToLocation": "ไปยังตำแหน่ง",
  "training.lessons.owner-move-stock.step1": "คำขอมีไว้สำหรับขอ ส่วนการย้ายเป็นงานของเจ้าของ ในหน้ากล่องจดหมายระหว่างร้าน แผงย้ายสต็อกให้คุณ — เจ้าของ — ส่งสต็อกตรงจากร้านนี้ไปยังร้านอื่นของคุณ โดยไม่มีคำขอและไม่ต้องรอ",
  "training.lessons.owner-move-stock.step2": "เลือกสินค้า ตำแหน่งต้นทาง และจำนวน แอปจะแสดงว่ามีสต็อกอยู่เท่าใดที่ตำแหน่งนั้น และการย้ายแต่ละครั้งจะเอาไปมากกว่านั้นไม่ได้เลย",
  "training.lessons.owner-move-stock.step3": "เลือกร้านปลายทาง และถ้าต้องการก็เลือกตำแหน่งที่แน่นอนที่นั่นด้วย หากร้านนั้นมี SKU เดียวกันอยู่แล้ว สต็อกจะรวมเข้ากับสินค้านั้น หากไม่มี สินค้าจะถูกคัดลอกไปพร้อมกับสต็อก",
  "training.lessons.owner-move-stock.step4": "ร้านทั้งสองเก็บบันทึกไว้ ร้านนี้แสดงการโอนออก อีกร้านแสดงการรับเข้า หากย้ายไม่ได้ — สต็อกไม่พอ หรือร้านอื่นไม่ใช่ของคุณ — จะไม่มีอะไรเคลื่อนย้าย และแอปจะบอกเหตุผล",
  "training.lessons.owner-move-stock.title": "ย้ายสต็อกระหว่างร้านของคุณเอง (แผน Business)",
  "plansLib.feature.pricing": "ราคาโละสต็อกและโรลล์แบ็ก",
